import { Scene, OBJLoader, OrbitCameraController, Light, Color } from "retiam";

const scene = new Scene({ canvas });
new OrbitCameraController(scene.camera, canvas);

// Add lighting for 3D model
const light = new Light({ position: [5, 10, 8], color: Color.WHITE, intensity: 1.2 });
scene.add(light);

// Asynchronously load 3D OBJ with smooth normals and MTL textures
const spaceship = await OBJLoader.load("/models/spaceship.obj", "smooth", true);
spaceship.transform.scale = 0.5;
spaceship.transform.position = [0, 0, 0];
scene.add(spaceship);
